  if (!Number.isInteger(target) || target < 1 || target > 1000000000) return 'target is a whole number from 1 to 10^9.';
  if (!Number.isInteger(maxDoubles) || maxDoubles < 0 || maxDoubles > 100) return 'maxDoubles is a whole number from 0 to 100.';
