function minMoves(target, maxDoubles) {
  // Try every exact number k of doubles. A forward plan is: add a0, double, add a1, double, ..., add ak,
  // so target = (1 + a0) * 2^k + a1 * 2^(k-1) + ... + ak. Paying for weights that are powers of two,
  // the cheapest choice is a0 = floor(target / 2^k) - 1 and the remainder in binary (its popcount).
  let best = Infinity;
  for (let k = 0; k <= maxDoubles && 2 ** k <= target; k++) {
    const high = Math.floor(target / 2 ** k);
    let rest = target % 2 ** k;
    let ones = 0;
    while (rest > 0) { ones += rest % 2; rest = Math.floor(rest / 2); }
    best = Math.min(best, k + (high - 1) + ones);
  }
  return best;
}

