function generate(rand, size) {
  if (size === 'small') {
    const target = 1 + Math.floor(rand() * 300);
    const maxDoubles = rand() < 0.2 ? 0 : Math.floor(rand() * 12);
    return [target, maxDoubles];
  }
  const pick = rand();
  let target;
  if (pick < 0.25) target = 1000000000 - Math.floor(rand() * 1000);
  else if (pick < 0.4) target = 2 ** (20 + Math.floor(rand() * 10)) - Math.floor(rand() * 2);
  else target = 1 + Math.floor(rand() * 1000000000);
  const maxDoubles = rand() < 0.3 ? Math.floor(rand() * 10) : Math.floor(rand() * 101);
  return [target, maxDoubles];
}
